import assert from 'node:assert/strict';
import {ClockReference} from '../reference/clock-reference.mjs';
const [base,token]=process.argv.slice(2);
const client=new ClockReference(base,token);
await client.renew();
const occurrence=new Date().toISOString();
const invalid=client.stage('in',{gps:{latitude:91,longitude:0,captured_at:occurrence}},occurrence);
assert.equal((await client.submit(invalid)).error.code,'invalid_gps');
await assert.rejects(client.submit(invalid),/explicit_repair_required/);
const repaired=client.withoutLocation(invalid);
assert.notEqual(repaired,invalid);
assert.equal(client.pending.get(repaired).command.occurred_at,occurrence);
const accepted=await client.submit(repaired);
assert.equal(accepted.status,200);
assert.equal((await client.receipt(repaired)).data.entry_id,accepted.data.entry_id);
assert.deepEqual(await client.submit(repaired),accepted);
const out=client.stage('out',{entry_id:accepted.data.entry_id},new Date().toISOString());
assert.equal((await client.submit(out)).status,200);
const old=client.pending.get(out).command;
const noop=await client.call('/time-entries/clock-out','POST',{...old,operation_id:crypto.randomUUID()});
assert.equal(noop.status,200);
const lateGPS=client.stage('out',{entry_id:accepted.data.entry_id,gps:{latitude:51.5,longitude:-0.12,captured_at:old.occurred_at}},old.occurred_at);
assert.equal((await client.submit(lateGPS)).error.code,'gps_immutable');
assert.equal((await client.submit(client.withoutLocation(lateGPS))).status,200);
const differing=await client.call('/time-entries/clock-out','POST',{...old,operation_id:crypto.randomUUID(),occurred_at:new Date().toISOString()});
assert.equal(differing.error.code,'time_different_end');
console.log('PASS staged occurrence retained/new identity explicit GPS omission; create once; query receipt; exact end no-op; different end requires correction');
